import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from gen import P
p=P("""# W5-A: SOV01 won with real orders only (no cheats). The high bridge 'Break
# Bridge' blows at f0 is repaired by an engineer the player trains (power plant,
# barracks) and walks -- escorted by the type-selected Conscripts -- to the
# revealed bridge hut (a real capture click). Then 25 more Conscripts walk round
# the American base's north edge to the Pentagon's east side and force-fire
# (Ctrl) the four sections; 'Win Condition 1' -> VICTORY. Generated by
# scripts/play/gen/mk_sov01.py -- edit the generator, not this file.
set render_every 3000
set on_quit continue
set campaign sov01t.MAP Nod
until 60 scene == campaign-load
click start
until 300 scene == game
until 60 bridge_destroyed >= 4
let broken = bridge_destroyed
until 2400 input_locked == 0
if units(0,SMCV) >= 1 then click unit 0:SMCV
if units(0,SMCV) >= 1 then key d
until 900 built(0,NACNST) >= 1
""")
p.build("NAPOWR").build("NAHAND")
p.train("SENGINEER", 2, 1)
p.add("until 1200 units(0,SENGINEER) >= 1")
# W6-02-11: idle units now engage at weapon range + 1 (not Sight), so the engineer
# walks INSIDE the Conscript group to (97,92) (it used to trail it while the escorts
# covered it from their Sight range), then on alone as before.
# R-210: with the height gate the Conscripts and civilians no longer take cliff
# steps, so the fight on the way plays out differently; the escort now stays with
# the engineer for the second leg too (alone it met three GIs at (100,111)).
# w7r2: since wave 7's threat scan the GIs by the road -- house 2's at
# (100,105..110), house 1's at (98..99,86..92) -- engage the column, and the
# engineer walking with it (or just behind) is shot. The Conscripts go first
# and fight both groups; the engineer follows once the fighting is over.
p.select_types(["E2"]).add("click cell 97 92", "until 900 sel_moving == 0", "wait 300")
p.select_types(["SENGINEER"]).add("click cell 97 92", "until 900 sel_moving == 0", "wait 60")
p.select_types(["E2", "SENGINEER"]).add("click cell 99 95", "until 1500 sel_moving == 0", "wait 30")
p.select_types(["SENGINEER"]).add("click cell 99 95", "until 1500 sel_moving == 0", "dump", "click unit 0:SENGINEER:0", "click building 4:CABHUT:1", "wait 20", "dump",
      "until 1800 bridge_destroyed < $broken", "assert units(0,SENGINEER) == 0", "assert outcome == RUNNING", "shot repaired")
p.train("E2", 2, 25)
# MR2 (human structures take their full fractional build time): the base comes
# up a few frames later, the fights on the way play out differently
# and the army was wiped out by the Pentagon (61 -> 4, RUNNING at f19733). Setting off
# 300 frames later (1800) it reaches the east side intact again.
p.add("wait 1800")
# MR1 (after L0: the original FastMath/_ftol and the frame timers): the old
# sweep -- clear the GIs in the (62..72, 84..85) corridor, then round to the
# gully bridge (50,84) for the Rhinos -- now loses the whole Conscript army to
# the base's two Vulcan pillboxes (71,84)/(71,86) and its GIs (61 -> 7 units,
# the Pentagon untouched). Instead the army walks straight to (72,40), east
# of the Pentagon: the pathfinder skirts the American base's north edge
# ((69,82) -> (60,64) -> (69,47)), the paratrooper reinforcements join on the
# way, and from the east side -- out of the Pentagon pillboxes' reach
# ((59/61,46), (59/61,53)) -- the type-selected Conscripts force-fire the four
# 180-HP sections (Ctrl, the loop below).
# w7r2: since wave 7's original speeds (Conscript Speed=4 raw leptons/frame)
# the army no longer outruns the two Vulcan pillboxes flanking the base's
# only entrance, (71,84)/(71,86) -- walking between them it lost 21 of 25
# men. Vulcan2 does 40 per 26 frames to a Conscript, the M1Carbine 7.5 per 25
# to the pillbox's steel (400 HP), so the massed army stops east of the gate
# and shoots both pillboxes out first (a plain attack order on the nearest).
p.select_types(["E2"]).add("click cell 82 85", "wait 30", "until 1500 sel_moving == 0", "dump")
def shoot_pills(n):
    for k in range(n):
        p.select_types(["E2"]).add("let pills = buildings(1,GAPILL)", "click building 1:GAPILL:near",
                                   "wait 30", "until 1200 buildings(1,GAPILL) < $pills", "dump")
shoot_pills(2)
# ... and the same for the four by the Pentagon, (59/61,46) and (59/61,53),
# which cover the road north at (60,53..60): from (61,64), out of their reach.
# The GI squad in the corridor (69..75,81..85) mows down a column walking
# past (a unit on a move order does not shoot back): the massed army picks
# the GI nearest it, one at a time, until none is within reach.
PICKS = int(os.environ.get("MK_SOV01_PICKS", "24"))
for _ in range(PICKS):
    p.select_types(["E2"]).add("click unit e:E1:near soft", "wait 50")
p.add("dump")
p.select_types(["E2"]).add("click cell 61 64", "wait 30", "until 1500 sel_moving == 0", "wait 60", "dump")
shoot_pills(4)
p.select_types(["E2"]).add("click cell 72 40", "wait 30", "until 2400 sel_moving == 0", "wait 60", "dump")
for k in range(10):
    for piece in ["CAWA2A","CAWA2B","CAWA2C","CAWA2D"]:
        g = f"outcome == RUNNING and buildings(4,{piece}) > 0"
        p.add(f"if {g} and units(0,HTNK) > 0 then click unit 0:HTNK:0",
              f"if {g} and units(0,E2) > carried(0) then click unit 0:E2:0 shift",
              f"if {g} then key t", f"if {g} then key t",
              f"if {g} then click building 4:{piece}:0 ctrl", "if outcome == RUNNING then wait 300")
    p.add("if outcome == RUNNING then dump")
p.add("until 3000 outcome == WON", "end expect WON")
p.save(sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "m-sov01-real.play"))
